contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10, "need exactly 10 wei");
        require(address(this).balance >= amount, "not enough balance");
        require(address(this) != c.bank(), "bank is not allowed for this rule");

        uint potBefore = c.pot();
        uint contractBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }

        uint potAfter = c.pot();
        uint contractBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;

        bool outcomeA = (potAfter == 0)
            && (contractBalanceAfter == 0)
            && (thisBalanceAfter == thisBalanceBefore - amount + potBefore + amount - 1);
        bool outcomeB = (potAfter == potBefore + amount)
            && (contractBalanceAfter == contractBalanceBefore + amount)
            && (thisBalanceAfter == thisBalanceBefore - amount);

        assert(!reverted && (outcomeA || outcomeB));
    }

    receive() external payable {}
}

