contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // Force the bank to be this test contract by having it deploy c.
        // Call play() as the bank with exactly the ticket amount.
        uint amount = 10;
        require(address(this).balance >= amount);

        uint beforeCaller = address(this).balance;
        uint beforePot = c.pot();

        c.play{value: amount}();

        uint afterCaller = address(this).balance;
        uint afterPot = c.pot();

        // General rule: if the caller is the bank, the payout branch (if taken)
        // sends pot - FEE_AMOUNT to the caller and FEE_AMOUNT to the bank, which
        // is also the caller. The caller's net gain is therefore exactly the pot
        // that was present before the call. This holds regardless of which random
        // branch executes, as long as the call succeeds.
        assert(afterCaller == beforeCaller + beforePot);
    }

    receive() external payable {}
}

