        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
        uint cBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;

        // General rule: with exactly 10 wei, play() never reverts, and if the bank is not the caller,
