        // (random==1) the caller received nothing and the pot increased by exactly 10 wei.
        assert(
            !reverted &&
            (
                c.bank() == address(this) ||
                (
                    thisBalanceAfter == thisBalanceBefore + 10 &&
                    cBalanceAfter == cBalanceBefore - 10 &&
                    potAfter == potBefore
                ) ||
                (
                    thisBalanceAfter == thisBalanceBefore &&
                    cBalanceAfter == cBalanceBefore + 10 &&
                    potAfter == potBefore + 10
                )
            )
        );
    }

    receive() external payable {}
}

